 const [activities,setActivities]=useState<string[]>([]);
 const [protection,setProtection]=useState<string[]>([]);
 const [sexDrive,setSexDrive]=useState('3');
 const [orgasm,setOrgasm]=useState('');
 const [sexNotes,setSexNotes]=useState('');
