 const [notice,setNotice]=useState('');
 const today=dateKey(new Date());
 const firstName=data.profile.display_name?.trim()||data.user.name.split(' ')[0]||'there';
 const moonToday=getMoonPhase(new Date(today+'T12:00:00'));
 const hormonal=['pill','hormonal_iud','implant','injection','patch','ring'].includes(data.profile.contraception_type??'');
 const fertile=Boolean(data.fertility_window&&today>=data.fertility_window.start_date&&today<=data.fertility_window.end_date);
 const ovulationDate=data.fertility_window?.ovulation_date??null;
 const daysToOvulation=ovulationDate?Math.round((new Date(ovulationDate+'T12:00:00').getTime()-new Date(today+'T12:00:00').getTime())/86400000):null;
 const periodDueToday=!hormonal&&data.days_until_estimate===0;
 const ovulationToday=!hormonal&&daysToOvulation===0;
 const phase=data.cycle_day==null?'Your cycle story begins when you log a period.':periodDueToday?'Estimated period day 1':ovulationToday?'Ovulation day':fertile?'Estimated fertile window':data.cycle_day<=5?'Menstrual phase':data.cycle_day<=Math.max(6,(data.profile.average_cycle_length??28)-14)?'Follicular phase (estimated)':'Luteal phase (estimated)';
 const week=useMemo(()=>{const d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const n=new Date(d);n.setDate(d.getDate()+i);return n;});},[selectedDate]);
 const monthDays=useMemo(()=>{const first=new Date(month.getFullYear(),month.getMonth(),1);const count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();return [...Array((first.getDay()+6)%7).fill(null),...Array.from({length:count},(_,i)=>i+1)];},[month]);
 const selectedMoon=getMoonPhase(new Date(selectedDate+'T12:00:00'));
 const groupedSymptoms=Array.from(new Set(symptoms.map(s=>s[2])));
 const moonDays=useMemo(()=>Array.from({length:30},(_,i)=>{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+i-14);return d;}),[today]);
