 const selectedIsFertile=Boolean(data.fertility_window&&selectedDate>=data.fertility_window.start_date&&selectedDate<=data.fertility_window.end_date);
 const selectedCyclePhase=selectedCycleDay==null||selectedCycleDay<1?'cycle phase not available':selectedIsFertile?'estimated fertile window':selectedCycleDay<=5?'menstrual phase (estimate)':selectedCycleDay<=Math.max(6,(data.profile.average_cycle_length??28)-14)?'follicular phase (estimate)':'luteal phase (estimate)';
 const moonSymbolicNote=selectedMoon.name==='Waxing crescent'||selectedMoon.name==='First quarter'?'Waxing Moon symbolism often centres on building momentum; choose one small intention.':selectedMoon.name==='Full moon'?'Full Moon symbolism often centres on reflection and release; notice what feels emotionally full.':selectedMoon.name==='Waning crescent'||selectedMoon.name==='Last quarter'?'Waning Moon symbolism often centres on simplifying and letting go; choose one thing to set down.':selectedMoon.name==='Waxing gibbous'?'Waxing gibbous symbolism can be a prompt to refine a plan rather than perfect it.':selectedMoon.name==='Waning gibbous'?'Waning gibbous symbolism can be a prompt to appreciate what is working and share what you have learned.':'New Moon symbolism often centres on beginnings; name an intention without pressuring yourself to act today.';
